def optimize_snow(override):
    override('Actors/Snow.cs', [('public Vec3 Direction;', 'public Vec3 Direction;\n    private struct FlakeSeed\n    {\n        public float X, VX, Y, VY, Z, VZ;\n    }\n    private readonly List<FlakeSeed> flakeSeeds = [];\n    private Rng flakeRng = new(0);'), ('// welcome to the land of unoptimized snow :)', '// These axes and random inputs are identical for every flake/cell.\n        var billboardLeft = World.Camera.Left * 0.50f;\n        var billboardUp = World.Camera.Up * 0.50f;'), ('var rng = new Rng(0);', ''), ('Vec3 point = new()', 'if (flakeSeeds.Count <= i)\n                {\n                    flakeSeeds.Add(new FlakeSeed {\n                        X = flakeRng.Float(area), VX = flakeRng.Float(5, 25),\n                        Y = flakeRng.Float(area), VY = flakeRng.Float(5, 25),\n                        Z = flakeRng.Float(area), VZ = flakeRng.Float(5, 25)\n                    });\n                }\n                var seed = flakeSeeds[i];\n                Vec3 point = new()'), ('rng.Float(area) + rng.Float(5, 25) * time * Direction.X', 'seed.X + seed.VX * time * Direction.X'), ('rng.Float(area) + rng.Float(5, 25) * time * Direction.Y', 'seed.Y + seed.VY * time * Direction.Y'), ('rng.Float(area) + rng.Float(5, 25) * time * Direction.Z', 'seed.Z + seed.VZ * time * Direction.Z'), ('populate.Add(Sprite.CreateBillboard(World, point, subtex, 0.50f, color));', 'populate.Add(new Sprite {\n                    Subtexture = subtex,\n                    A = point + billboardLeft + billboardUp,\n                    B = point - billboardLeft + billboardUp,\n                    C = point - billboardLeft - billboardUp,\n                    D = point + billboardLeft - billboardUp,\n                    Color = color\n                });')])
